import '../../../../../../Core/Models/cart_itemes.dart';import '../../../../../../Core/Storage/Remote/api_endpoints.dart';import '../../../../../../Core/Storage/Remote/api_service.dart';import '../entity/coupons_model.dart';import '../entity/removed_coupons.dart';class CartSources {  static Future<CartItemsModel> getCarts() async {    final response = await DioHelper.getData(      path: ApiEndpoints.cart,    );    final data = CartItemsModel.fromJson(response.data["data"]);    return data;  } static Future<CartItemsModel> removeFromCart({required int id}) async {    final response = await DioHelper.deleteData(      path: "${ApiEndpoints.removeCart}/$id",    );    final data = CartItemsModel.fromJson(response.data["data"]);    return data;  } static Future<CartItemsModel> clearCart() async {    final response = await DioHelper.postData(      path: ApiEndpoints.clearCart,    );    final data = CartItemsModel.fromJson(response.data["data"]);    return data;  }  static Future<CartItemsModel> updateFromCart(      {required int id, required int newQuantity}) async {    final response = await DioHelper.putData(      data: {"quantity": newQuantity},      path: "${ApiEndpoints.updateCart}/$id",    );    final data = CartItemsModel.fromJson(response.data["data"]);    return data;  }  //* Coupons  static Future<CouponsModel> applyCoupon({required String code}) async {    final response = await DioHelper.postData(      data: {"code": code},      path: ApiEndpoints.applyCoupon,    );    final data = CouponsModel.fromJson(response.data["data"]);    return data;  }  static  Future<RemovedCouponsModel> removeCoupon({required String code}) async {    final response = await DioHelper.postData(      data: {"code": code},      path: ApiEndpoints.removeCoupon,    );    final data = RemovedCouponsModel.fromJson(response.data["data"]);    return data;  }}